//! Icon geometry taken from Tabler Icons.
//!
//! Generated by `tools/icon-import`. Do not edit: run
//! `scripts/import-icons.sh` instead, and change `tools/icon-import/icons.txt`
//! to change which icon stands behind which glyph.
//!
//! Tabler Icons is Copyright (c) 2020-2024 Paweł Kuna and is offered under the
//! MIT licence, whose terms are reproduced in `licenses/LICENSE-Tabler.txt`.
//! The MIT licence imposes no copyleft, so this geometry travels inside an
//! AGPL binary without changing anything about it, as long as the notice
//! travels with it.
//!
//! Coordinates are the source artwork's 24 unit box scaled to the 1000 unit
//! box `super::UNITS` defines, so 1 source pixel is 41 and two thirds units.
//! Curves are cubics because that is what the source uses; quadratics and
//! elliptical arcs were resolved into cubics at import time, in `f64`, before
//! anything was rounded.

use super::Cmd;
use crate::Glyph;

/// Every outline of one glyph.
///
/// Deliberately total rather than fallible. A glyph with no artwork would draw
/// nothing at all, and nothing at all is invisible rather than wrong, so the
/// compiler is made to refuse a `Glyph` variant that `icons.txt` does not
/// name.
pub(super) fn outline(glyph: Glyph) -> &'static [&'static [Cmd]] {
    match glyph {
        Glyph::App => APP,
        Glyph::Book => BOOK,
        Glyph::Note => NOTE,
        Glyph::Clock => CLOCK,
        Glyph::Settings => SETTINGS,
        Glyph::Folder => FOLDER,
        Glyph::Chart => CHART,
        Glyph::Search => SEARCH,
        Glyph::Reader => READER,
        Glyph::Power => POWER,
        Glyph::Grid => GRID,
        Glyph::Circle => CIRCLE,
        Glyph::Check => CHECK,
        Glyph::Terminal => TERMINAL,
        Glyph::Chat => CHAT,
        Glyph::News => NEWS,
        Glyph::Rss => RSS,
        Glyph::Light => LIGHT,
        Glyph::Close => CLOSE,
        Glyph::Download => DOWNLOAD,
        Glyph::Bookmark => BOOKMARK,
        Glyph::Heart => HEART,
        Glyph::Filter => FILTER,
        Glyph::Person => PERSON,
        Glyph::Tag => TAG,
        Glyph::Globe => GLOBE,
        Glyph::Refresh => REFRESH,
        Glyph::More => MORE,
        // Drawn with the artwork of `Headphones`. See `Glyph::Bluetooth`.
        Glyph::Bluetooth => HEADPHONES,
        Glyph::Key => KEY,
        Glyph::Magnet => MAGNET,
        Glyph::Play => PLAY,
        Glyph::Pause => PAUSE,
        Glyph::Rewind30 => REWIND30,
        Glyph::Forward30 => FORWARD30,
        Glyph::VolumeDown => VOLUME_DOWN,
        Glyph::VolumeUp => VOLUME_UP,
        Glyph::MoreVertical => MORE_VERTICAL,
        Glyph::Previous => PREVIOUS,
        Glyph::Next => NEXT,
        Glyph::Trash => TRASH,
        Glyph::Wifi => WIFI,
        Glyph::Battery => BATTERY,
        Glyph::Plus => PLUS,
        Glyph::Headphones => HEADPHONES,
        Glyph::Minus => MINUS,
        Glyph::ChessWhiteKing => CHESS_WHITE_KING,
        Glyph::ChessWhiteQueen => CHESS_WHITE_QUEEN,
        Glyph::ChessWhiteRook => CHESS_WHITE_ROOK,
        Glyph::ChessWhiteBishop => CHESS_WHITE_BISHOP,
        Glyph::ChessWhiteKnight => CHESS_WHITE_KNIGHT,
        Glyph::ChessWhitePawn => CHESS_WHITE_PAWN,
        Glyph::ChessBlackKing => CHESS_BLACK_KING,
        Glyph::ChessBlackQueen => CHESS_BLACK_QUEEN,
        Glyph::ChessBlackRook => CHESS_BLACK_ROOK,
        Glyph::ChessBlackBishop => CHESS_BLACK_BISHOP,
        Glyph::ChessBlackKnight => CHESS_BLACK_KNIGHT,
        Glyph::ChessBlackPawn => CHESS_BLACK_PAWN,
        Glyph::LetterCheck => LETTER_CHECK,
        Glyph::Hash => HASH,
        Glyph::Lattice => LATTICE,
        Glyph::Puzzle => PUZZLE,
        Glyph::Remote => REMOTE,
        Glyph::Dice => DICE,
        Glyph::Counters => COUNTERS,
        Glyph::Question => QUESTION,
        Glyph::Sword => SWORD,
        Glyph::Compass => COMPASS,
        Glyph::Books => BOOKS,
        Glyph::BookDownload => BOOK_DOWNLOAD,
        Glyph::Stack => STACK,
        Glyph::Document => DOCUMENT,
        Glyph::Article => ARTICLE,
        Glyph::Cards => CARDS,
        Glyph::Yarn => YARN,
        Glyph::Music => MUSIC,
        Glyph::Notebook => NOTEBOOK,
        Glyph::Quote => QUOTE,
        Glyph::Feather => FEATHER,
        Glyph::Binoculars => BINOCULARS,
        Glyph::Mail => MAIL,
        Glyph::CalendarCheck => CALENDAR_CHECK,
        Glyph::Checklist => CHECKLIST,
        Glyph::House => HOUSE,
        Glyph::Cutlery => CUTLERY,
        Glyph::Collage => COLLAGE,
        Glyph::FeedPage => FEED_PAGE,
        Glyph::Photo => PHOTO,
        Glyph::Prompt => PROMPT,
        // Board pieces, the keyboard keys and the puzzle grids are drawn in
        // `vector::shapes` rather than imported, for the reasons on `HAND_DRAWN`.
        Glyph::BlackDisc
        | Glyph::WhiteDisc
        | Glyph::BlackDraughtsKing
        | Glyph::WhiteDraughtsKing
        | Glyph::BlackDraughtsMan
        | Glyph::WhiteDraughtsMan
        | Glyph::BoardPoint
        | Glyph::Mill
        | Glyph::LegalPoint
        | Glyph::Backspace
        | Glyph::Shift
        | Glyph::CrosswordGrid
        | Glyph::CellGrid => &[],
    }
}

